  (* [comment removed for export] *)
  Lemma w4f_loop4 : forall (fuel : nat) q pt bits mm (x1 x7 a2 a3 x23 x24 x26 x27 c x31 : word),
    YM mm -> OPk <= DST + q <= SE -> SE - (DST + q) < 4 * Z.of_nat fuel ->
    0 <= pt -> (pt = 0 \/ pt + 8 <= n) -> 0 <= bits <= 64 ->
    evtF asegs RNG POST (ST 0x8fbb4 mm x1 x7 (Z_to_bv 64 (SS + pt)) (Z_to_bv 64 (DST + q)) a2 a3 (Z_to_bv 64 bits)
                             (Z_to_bv 64 SS) (Z_to_bv 64 (SS + 8)) (Z_to_bv 64 (DST + q)) (Z_to_bv 64 (SE - 3))
